def run(context):
    # Extract data
    holdings = context['portfolio.holdings']
    snapshots = context['scores.stage_snapshots']

    # Process data for decisions
    add_candidates = []
    trim_candidates = []
    for holding in holdings:
        # Find matching snapshot
        snapshot = next((s for s in snapshots if s['symbol'] == holding['symbol']), None)
        if snapshot:
            # Example decision logic
            if snapshot['stage'] < 3 and snapshot['can_slim_score'] > 7:
                add_candidates.append(holding['symbol'])
            elif snapshot['stage'] > 3:
                trim_candidates.append(holding['symbol'])

    return {
        'add_candidates': add_candidates,
        'trim_candidates': trim_candidates
    }

